'use strict';
// Meeting and risk workflows retain the original execution, snapshots and source viewers.
const aaBase={configPanel,workbench,awToolbar,twPreview,awPromptModal,awRiskEditor,awMeeting,awMeetingRegular,awMeetingTable,awMeetingRisk,awMeetingQA,awRisk,awRows,awExportableRows,awReviewHTML,awReportBody,awOutputRows,modalContent,handleAction,render,meetingFilterModal,validate};
const AA_IDS=['meeting','risk'];
const aaViews={};
function aaView(id=state.toolId){return aaViews[id]??={task:null,page:1,groupPage:1,limits:{},riskQuery:'',riskOpen:[],advanced:false,scheme:false};}
function aaTaskView(task){const a=aaView(task.toolId),v=av(task.toolId),signature=JSON.stringify([task.id,v.resultQuery,v.resultScope,v.resultFolder,v.riskFilter,v.riskGroup,v.meetingView,task.meetingFilters]);if(a.signature!==signature){a.signature=signature;a.task=task.id;a.page=1;a.groupPage=1;a.limits={};}return a;}
function aaActive(){return state.view==='tool'&&AA_IDS.includes(state.toolId);}
function aaNumberInput(el){const key=el.dataset.config;if(!aaActive()||currentTask()||!el.closest('.aa-config')||!['similarityThreshold','minClusterSize'].includes(key))return false;const n=Number(el.value),valid=el.value!==''&&Number.isFinite(n)&&n>=+el.min&&n<=+el.max&&(key!=='minClusterSize'||Number.isInteger(n));ws().config[key]=el.value;el.setAttribute('aria-invalid',String(!valid));let error=el.parentElement.querySelector('.aa-number-error');if(!error){error=document.createElement('span');error.className='aa-number-error';error.setAttribute('role','status');el.parentElement.append(error);}error.textContent=valid?'':key==='minClusterSize'?'请输入1–20的整数':'请输入0–100之间的数值';persist();return true;}
TW_META.meeting=['添加会议纪要','设置会议分析提示词','整理会议决策和议题，追踪同类事项的讨论、调整与落实。'];
TW_META.risk=['添加核查资料','设置风险分析内容','选择审计关注的风险点，逐项检查资料，核对线索及原文依据。'];
PROMPT_STAGES.meeting.forEach(s=>s[1]=s[0]==='regular'?'会议与议题':'会议风险');
PROMPT_STAGES.risk.forEach(s=>s[1]='风险检查要求');
const AA_DEFAULTS={meeting:{regular:'逐份整理会议名称、会议日期、参会和列席人员，逐项摘录议题、涉及金额及单位、形成的决策、责任人和落实要求。保留同类议题的前后变化及原文来源；未载明的信息如实标注。',risk:'围绕会议涉及的预算调整、采购决策、资金支付、授权审批和责任落实查找需核验事项。逐项说明涉及的会议、原文依据、前后变化及需补充核对的业务资料，不将线索直接认定为审计问题。'},risk:{risk:'按照已选风险点及检查说明核查每份资料，列出相关事项、分析说明和原文依据。区分待核验线索、未见线索与资料不足，保留风险点层级和来源；资料未说明的内容不得补写。'}};
const aaOldDefaults={};
for(const id of AA_IDS){aaOldDefaults[id]={};for(const key of Object.keys(AA_DEFAULTS[id])){aaOldDefaults[id][key]=awDefaults[id][key].content;awDefaults[id][key].content=AA_DEFAULTS[id][key];}}
function aaPrepare(c){for(const [key,text] of Object.entries(AA_DEFAULTS[state.toolId])){const s=c.stages[key],old=aaOldDefaults[state.toolId][key];if(s&&!s.customized&&s.origin!=='personal'&&[old,old.replace('未取得','未提取到')].includes(s.content))s.content=text;}}
function aaRule(c,key,title,help,locked){const s=c.stages[key];return '<section class="aa-rule"><div><h3>'+title+'</h3>'+A(locked?'查看':'调整','aw-prompt','data-stage="'+key+'"')+'</div><p>'+help+'</p><p class="aa-rule-text" title="'+E(s.content)+'">'+E(s.content)+'</p></section>';}
function aaSchemes(c,locked){return '<section class="aa-scheme"><label for="aa-scheme">使用方案</label><select id="aa-scheme" aria-label="选择分析方案" data-config="template" '+(locked?'disabled':'')+'>'+options([...new Set([tool(state.toolId).template,...state.templates.filter(t=>t.toolId===state.toolId&&!t.stage).map(t=>t.name),c.template])],c.template)+'</select></section>';}
function aaSchemeTools(){const a=aaView();return '<details class="aa-settings" data-aa-details="scheme" '+(a.scheme?'open':'')+'><summary>方案管理</summary><div class="aa-scheme-tools">'+B('另存个人方案','aw-save-scheme','sm')+B('导入方案','aw-import-config','ghost sm')+B('导出方案','v2-export-config','ghost sm')+'</div></details>';}
function aaRiskChoices(c,locked){const q=aaView('risk').riskQuery.trim().toLowerCase(),rows=c.riskNodes.filter(r=>[r.name,r.path,r.description].join(' ').toLowerCase().includes(q)),groups=[...new Set(rows.map(r=>r.path.split('/')[0].trim()))];return groups.map(g=>'<section class="aa-check-group"><h4>'+E(g)+'</h4>'+rows.filter(r=>r.path.split('/')[0].trim()===g).map(r=>'<label class="aa-check-row"><input type="checkbox" data-change="risk-check" value="'+E(r.name)+'" '+(c.checks.includes(r.name)?'checked':'')+' '+(locked?'disabled':'')+'><span><b>'+E(r.name)+'</b><small title="'+E(r.path)+'">'+E(r.description)+'</small></span></label>').join('')+'</section>').join('')||'<p class="aa-empty-small">没有匹配的风险点</p>';}
configPanel=function(){const html=aaBase.configPanel();if(!aaActive())return html;const c=awConfig(),locked=!!currentTask(),a=aaView(),root=document.createElement('div');root.innerHTML=html;const panel=root.querySelector('aside');if(!panel)return html;if(!locked)aaPrepare(c);panel.classList.add('aa-config');panel.querySelector('.ew-panel-head h2').innerHTML=(locked?'':'<span class="tw-step">Step 3</span>')+(state.toolId==='meeting'?'设置会议分析提示词':'设置风险分析内容');let body='<p class="aa-config-intro">'+(locked?'本次执行时的设置，只读查看。':state.toolId==='meeting'?'先整理会议与议题，再按需分析风险或提问。':'勾选要检查的风险点，添加的资料均参与核查。')+'</p>'+aaSchemes(c,locked);
 if(state.toolId==='meeting')body+=aaRule(c,'regular','会议与议题','提取决策内容、金额、人员及落实要求。',locked)+'<details class="aa-settings" data-aa-details="advanced" '+(a.advanced||locked?'open':'')+'><summary>议题聚类设置</summary><p>将不同会议中的相近议题归在一起。</p><div class="aa-number-grid"><label>相似度阈值（%）<input aria-label="议题相似度阈值" data-config="similarityThreshold" type="number" min="0" max="100" step="1" value="'+E(c.similarityThreshold)+'" '+(locked?'disabled':'')+'></label><label>每组最少议题数<input aria-label="最小聚类数" data-config="minClusterSize" type="number" min="1" max="20" step="1" value="'+E(c.minClusterSize)+'" '+(locked?'disabled':'')+'></label></div><p>阈值越高，归组要求越严格；不会改变本次资料范围。</p></details>'+aaRule(c,'risk','后续风险分析','生成风险报告时使用，不随议题整理自动执行。',locked);
 else body+='<section class="aa-risk-selection"><div class="aa-section-head"><h3>检查风险点 <strong>'+c.checks.length+'</strong></h3>'+A(locked?'查看详情':'管理风险点','aw-risk-editor')+'</div>'+(!locked?'<div class="aa-check-actions">'+A('全选','aw-risk-all')+A('清空','aw-risk-none')+'</div>':'')+'<div class="search aa-risk-search">'+I('search','icon-sm')+'<input id="aa-risk-query" data-aa-input="risk-search" placeholder="查找风险点" aria-label="查找风险点" value="'+E(a.riskQuery)+'"></div><div id="aa-risk-choices">'+aaRiskChoices(c,locked)+'</div></section>'+aaRule(c,'risk','检查要求','说明如何识别线索、核对证据。',locked)+'<details class="aa-settings" data-aa-details="advanced" '+(a.advanced||locked?'open':'')+'><summary>检查方式</summary><select data-config="mode" aria-label="检查方式" '+(locked?'disabled':'')+'><option value="逐关注点检查各文件" '+(c.mode==='逐关注点检查各文件'?'selected':'')+'>按风险点逐项检查</option><option value="逐文件检查全部关注点" '+(c.mode==='逐文件检查全部关注点'?'selected':'')+'>按文件集中检查</option></select><p>按风险点：每次检查一个风险点。按文件：一次检查文件的全部风险点。两种方式均覆盖所选范围。</p></details>';
 if(!locked)body+=aaSchemeTools()+(state.toolId==='meeting'?'<div class="aa-import">'+B('导入已有结果','v3-meeting-import','ghost sm')+'</div>':'');panel.querySelector('.ew-config-body').innerHTML=body;return root.innerHTML;
};
awToolbar=function(task){const html=aaBase.awToolbar(task);if(!task||!AA_IDS.includes(task.toolId))return html;const root=document.createElement('div');root.innerHTML=thResultHeader(html,'.aw-command-actions',task);if(task.toolId==='meeting'){if(task.riskGenerating)root.querySelector('.tag')?.replaceWith(Object.assign(document.createElement('span'),{className:'tag blue',textContent:'报告生成中'}));const exp=root.querySelector('[data-action=export]'),missing=ws().subtab==='risk'&&!task.meetingRisk||ws().subtab==='qa'&&!task.chats?.length;if(exp&&missing){exp.setAttribute('disabled','');exp.title=ws().subtab==='risk'?'请先生成风险报告':'暂无问答记录';}}return root.innerHTML;};
workbench=function(){const task=currentTask();if(aaActive()&&task&&!trMode()&&task.status!=='running')configExpanded=false;let html=aaBase.workbench();if(!aaActive())return html;const root=document.createElement('div');root.innerHTML=html;root.firstElementChild?.classList.add('aa-workspace');if(!task){const run=root.querySelector('[data-action=run]');if(run)run.textContent=state.toolId==='meeting'?'开始分析':'开始分析';if(!twDocs().length)root.querySelector('.tw-empty-small')?.remove();}return root.innerHTML;};
twPreview=function(){const html=aaBase.twPreview();if(!aaActive()||twDocs().length)return html;const root=document.createElement('div');root.innerHTML=html;const empty=root.querySelector('.ef-empty');if(empty)empty.innerHTML='<span class="ef-empty-symbol">'+I(state.toolId==='meeting'?'message':'shield')+'</span><h2>'+(state.toolId==='meeting'?'梳理会议决策，追踪议题变化':'围绕风险点，逐项核查资料')+'</h2><p>'+(state.toolId==='meeting'?'整理会议与议题，对照不同会议中的金额、决策和落实要求。':'按审计关注点查找相关事项，保留分析说明和原文依据。')+'</p><p class="aa-preview-guide">先添加资料，再设置右侧'+(state.toolId==='meeting'?'分析要求。':'检查内容。')+'</p>';return root.innerHTML;};
awPromptModal=function(p){const html=aaBase.awPromptModal(p);if(!aaActive())return html;const root=document.createElement('div');root.innerHTML=html;root.querySelector('.modal')?.classList.add('aa-prompt-dialog');const locked=!!currentTask()&&!p.secondary;root.querySelector('.modalhead h2').textContent=locked?'执行时的分析要求':p.secondary?'设置风险报告要求':'设置分析要求';root.querySelector('.modalhead p').textContent=p.secondary?'用于生成下一份风险报告，已完成的会议议题保持不变。':locked?'按执行时的设置只读查看。':'按本次审计关注内容调整，应用后用于本次分析。';root.querySelectorAll('.field>span').forEach(n=>{if(n.textContent==='提示词模板')n.textContent='要求模板';});root.querySelectorAll('optgroup').forEach(n=>n.label=n.label.replace('系统提示词','系统预设').replace('个人提示词','个人预设'));const store=root.querySelector('[data-action=aw-store-prompt]');if(store)store.textContent='另存个人要求';root.querySelector('.aw-prompt-bottom>span').textContent=locked?'':p.secondary?'应用要求后，点击“生成风险报告”。':'应用后返回页面，确认资料再开始分析。';const save=root.querySelector('[data-action=aw-prompt-save]');if(save)save.textContent='应用要求';return root.innerHTML;};
awRiskEditor=function(p){const html=aaBase.awRiskEditor(p),root=document.createElement('div');root.innerHTML=html;root.querySelector('.modal')?.classList.add('aa-risk-editor-dialog');root.querySelector('.modalhead h2').textContent=currentTask()?'本次检查风险点':'管理检查风险点';root.querySelector('.modalhead p').textContent='设置风险点、业务分类和检查说明，勾选本次要检查的项目。';const heads=root.querySelectorAll('thead th');heads[2].innerHTML='业务分类 <b class="red">*</b>';root.querySelector('.aw-editor-bar').insertAdjacentHTML('afterend','<div class="search aa-editor-search">'+I('search','icon-sm')+'<input data-aa-input="risk-editor-search" value="'+E(p.editorQuery||'')+'" placeholder="查找名称、分类或检查说明" aria-label="查找风险点清单"></div>');root.querySelectorAll('tbody tr').forEach((tr,i)=>{tr.hidden=!([p.nodes[i].name,p.nodes[i].path,p.nodes[i].description].join(' ').toLowerCase().includes((p.editorQuery||'').toLowerCase()));tr.dataset.aaRiskIndex=i;});return root.innerHTML;};
function aaPager(kind,count,page,size,unit='条'){const pages=Math.max(1,Math.ceil(count/size));return '<footer class="aa-pagination"><span>共 <strong>'+count+'</strong> '+unit+'</span><div>'+B('上一页','aa-page','ghost sm','data-kind="'+kind+'" data-step="-1" '+(page<=1?'disabled':''))+'<span>'+page+' / '+pages+'</span>'+B('下一页','aa-page','ghost sm','data-kind="'+kind+'" data-step="1" '+(page>=pages?'disabled':''))+'</div></footer>';}
function aaResultTools(task,risk=false){const v=av(),f=task.meetingFilters,active=v.resultQuery||v.resultScope!=='all'||v.resultFolder||f;return '<div class="aa-result-tools"><div class="search">'+I('search','icon-sm')+'<input id="aw-result-query" data-aw-input="result" aria-label="搜索分析结果" value="'+E(v.resultQuery)+'" placeholder="'+(risk?'查找风险点、线索或资料':'查找会议、议题或人员')+'"></div><select data-aa-change="scope" aria-label="结果资料范围"><option value="all">全部资料</option>'+[...new Set((task.result||[]).map(r=>r.doc))].filter(id=>file(id)&&auditFileAccess(file(id)).read).map(id=>'<option value="'+E(id)+'" '+(v.resultScope===id?'selected':'')+'>'+E(file(id).name)+'</option>').join('')+'</select>'+(!risk?B('筛选'+(f?' · 已应用':''),'meeting-filter',f?'soft sm':'sm'):'')+(active?A('清除筛选','aw-clear'):'')+'</div>';}
awMeeting=function(task){const a=aaTaskView(task),v=av(),main=['risk','qa'].includes(ws().subtab)?ws().subtab:'regular',rows=awMeetingFiltered(task),all=(task.result||[]).filter(r=>file(r.doc)&&auditFileAccess(file(r.doc)).read);return '<div class="aa-business-tabs">'+awTabs([['regular','会议议题'],['risk','风险报告'],['qa','会议问答']],main,'meeting-tab')+'</div>'+(main==='risk'?awMeetingRisk(task):main==='qa'?awMeetingQA(task):'<header class="aa-result-heading"><h2 title="'+E(task.name)+'">'+E(task.name)+'</h2><span><strong>'+new Set(all.map(r=>r.doc)).size+'</strong> 次会议</span><button class="link aa-count-link" data-action="aw-all-topics" title="查看全部议题清单"><strong>'+all.length+'</strong> 项议题</button></header>'+aaResultTools(task)+'<div class="aa-viewbar">'+awTabs([['topics','议题聚类'],['meetings','会议顺序'],['all','议题清单']],v.meetingView,'aw-meeting-view')+'<span>匹配 <strong>'+rows.length+'</strong> 项议题</span></div>'+(rows.length?awMeetingRegular(task,rows):'<div class="aa-empty"><h3>没有匹配的会议议题</h3><p>可调整搜索或筛选条件。</p>'+B('清除筛选','aw-clear','sm')+'</div>'));};
awMeetingTable=function(task,rows){const modalList=modal==='aw-all-topics',a=modalList?modalData:aaTaskView(task),pageKey=modalList?'aaPage':'page',extras=[...new Set(rows.flatMap(r=>Object.keys(r.extraFields||{})))];if(modalList){const signature=JSON.stringify([a.query,a.doc,a.topic]);if(a.aaSignature!==signature){a.aaSignature=signature;a.aaPage=1;}}a[pageKey]=Math.max(1,Math.min(a[pageKey]||1,Math.ceil(rows.length/20)||1));const table=awTable(['会议 / 日期','议题与内容','金额（万元）','参会 / 列席人员',...extras.map(E),'来源'],pageItems(rows,a[pageKey],20).map(r=>['<b>'+E(r.title)+'</b><div class="aw-caption">'+E(r.date||'未提取到日期')+'</div>','<button class="link aw-topic-link" data-action="aw-review" data-id="'+E(r.doc)+'" data-index="'+task.result.indexOf(r)+'">'+E(r.topicName||r.topic)+'</button><p class="aw-table-excerpt" title="'+E(r.excerpt)+'">'+E(r.excerpt)+'</p>',E(r.amount==null||r.amount===''?'未提取到':String(r.amount).replace(' 万元','')),E(r.participants||'未提取到')+'<div class="aw-caption">列席：'+E(r.observers||'未提取到')+'</div>',...extras.map(k=>E(ewDisplay(r.extraFields?.[k])||'未提取到')),awReviewLink(task,r,'议题详情')]),'aw-meeting-table').replace('<table class=','<table style="min-width:'+(1050+extras.length*160)+'px" class=');return table+aaPager(modalList?'topics-modal':'meeting',rows.length,a[pageKey],20,'项议题');};
awMeetingRegular=function(task,rows){const v=av(),a=aaTaskView(task);if(v.meetingView==='all')return '<div class="aa-meeting-table-area">'+awMeetingTable(task,rows)+'</div>';const byMeeting=v.meetingView==='meetings',groups=byMeeting?[...new Set(rows.map(r=>r.doc))].sort((x,y)=>(rows.find(r=>r.doc===y).date||'').localeCompare(rows.find(r=>r.doc===x).date||'')):[...new Set(rows.map(r=>r.topic||'未归类议题'))];let chosen=byMeeting?v.meetingDoc:v.meetingTopic;if(!groups.includes(chosen)){chosen=groups[0];if(byMeeting)v.meetingDoc=chosen;else v.meetingTopic=chosen;a.page=1;}const details=rows.filter(r=>(byMeeting?r.doc:r.topic||'未归类议题')===chosen);a.groupPage=Math.max(1,Math.min(a.groupPage,Math.ceil(groups.length/15)||1));return '<div class="aw-meeting-layout aa-meeting-layout"><div class="aa-mobile-group"><select data-aa-change="meeting-group" aria-label="选择'+(byMeeting?'会议':'议题聚类')+'">'+pageItems(groups,a.groupPage,15).map(g=>{const rs=rows.filter(r=>(byMeeting?r.doc:r.topic||'未归类议题')===g);return '<option value="'+E(g)+'" '+(g===chosen?'selected':'')+'>'+E(byMeeting?rs[0]?.title:g)+' · '+rs.length+'项议题</option>';}).join('')+'</select><div>'+B(I('back','icon-sm'),'aa-page','ghost sm','data-kind="meeting-groups" data-step="-1" aria-label="上一组列表" '+(a.groupPage<=1?'disabled':''))+'<span>'+a.groupPage+' / '+Math.ceil(groups.length/15)+'</span>'+B(I('chevron','icon-sm'),'aa-page','ghost sm','data-kind="meeting-groups" data-step="1" aria-label="下一组列表" '+(a.groupPage>=Math.ceil(groups.length/15)?'disabled':''))+'</div></div><div class="aa-group-column"><nav class="aw-meeting-groups" aria-label="'+(byMeeting?'会议列表':'议题聚类')+'">'+pageItems(groups,a.groupPage,15).map(g=>{const rs=rows.filter(r=>(byMeeting?r.doc:r.topic||'未归类议题')===g),r=rs[0];return '<button class="'+(g===chosen?'active':'')+'" data-action="aw-meeting-select" data-id="'+E(g)+'" aria-current="'+(g===chosen)+'"><strong>'+E(byMeeting?r.title:g)+'</strong><span>'+E(byMeeting?r.date||'日期未提取':new Set(rs.map(r=>r.doc)).size+' 次会议')+' · '+rs.length+' 项议题</span></button>';}).join('')+'</nav>'+aaPager('meeting-groups',groups.length,a.groupPage,15,byMeeting?'次会议':'类议题')+'</div><div class="aw-meeting-detail"><div class="aw-section-heading"><h3>'+E(byMeeting?details[0]?.title:chosen)+'</h3><span>'+details.length+' 项议题</span></div>'+awMeetingTable(task,details)+'</div></div>';};
awMeetingRisk=function(task){const count=new Set((task.result||[]).filter(r=>file(r.doc)&&auditFileAccess(file(r.doc)).read).map(r=>r.doc)).size;if(!task.meetingRisk){if(task.riskGenerating)return '<div class="aa-empty" role="status"><span class="ef-empty-symbol">'+I('shield')+'</span><h2>正在生成风险报告</h2><p>会议议题可继续查看，完成后在此阅读报告。</p></div>';return '<div class="aa-empty aa-report-start"><span class="ef-empty-symbol">'+I('shield')+'</span><h2>'+(task.riskError?'风险报告未完成':'核查会议决策与后续落实')+'</h2><p>'+(task.riskError?'会议议题已保留，可重新生成风险报告。':'围绕预算调整、采购决策、资金支付等事项，整理待核验线索和来源。')+'</p><div>'+B('调整分析要求','aw-risk-prompt','sm')+B(task.riskError?'重试生成报告':'生成风险报告','meeting-risk','primary sm',task.result.length?'':'disabled')+'</div></div>';}
 return '<div class="aa-report-head"><h2>会议风险核查报告</h2><span>'+count+' 次会议</span><div>'+A('分析要求','aw-risk-prompt')+B(task.riskGenerating?'正在生成…':'重新生成','meeting-risk','sm',task.riskGenerating?'disabled':'')+'</div></div>'+(task.riskError?'<div class="aa-status-note">重新生成未完成，以下保留上次报告。</div>':task.riskGenerating?'<div class="aa-status-note" role="status">正在生成新报告，以下保留上次报告。</div>':'')+'<div class="aw-report-jump"><label>报告章节 <select aria-label="报告章节" data-aw-change="report-section">'+AW_REPORT_SECTIONS.map(([k,n])=>'<option value="'+k+'">'+E(k==='conclusion'?'核查建议':n)+'</option>').join('')+'</select></label><span>按事项核对线索与来源</span></div><div id="aw-report" class="aw-results-scroll aw-report aa-report">'+awReportBody(task)+'</div>';};
awReportBody=function(task){const html=aaBase.awReportBody(task),root=document.createElement('div');root.innerHTML=html;const h=root.querySelector('#aw-report-conclusion h2');if(h)h.textContent='七、核查建议';return root.innerHTML;};
awMeetingQA=function(task){const html=aaBase.awMeetingQA(task),root=document.createElement('div');root.innerHTML=html;const head=root.querySelector('.aw-qa-header');head.querySelector('h2').textContent='查问会议决策与落实情况';head.querySelector('[data-action=save-chat]')?.remove();const clear=head.querySelector('[data-action=clear-chat]');if(clear){clear.textContent='清空问答';if(!task.chats?.length)clear.setAttribute('disabled','');}root.querySelector('.aw-chat-welcome h3')?.replaceChildren(document.createTextNode('围绕本次会议提问'));root.querySelector('.aw-chat-welcome p')?.replaceChildren(document.createTextNode('可追踪同一事项的讨论、决策和后续安排。'));const send=root.querySelector('[data-action=send-chat]');if(send&&!av().questionDraft?.trim())send.setAttribute('disabled','');return root.innerHTML;};
function aaRiskStatus(r){return ['hit','nohit','insufficient'].includes(r.findingStatus)?r.findingStatus:'hit';}
awRows=function(task){if(task.toolId!=='risk')return aaBase.awRows(task);const v=av('risk'),q=v.resultQuery.trim().toLowerCase();return (task.result||[]).filter(r=>{const d=file(r.doc);return d&&auditFileAccess(d).read&&(v.resultScope==='all'||r.doc===v.resultScope)&&(!v.resultFolder||d.space===v.resultFolder.space&&underFolder(d.folder,v.resultFolder.path))&&[d.name,r.check,r.riskPath,r.detail,r.excerpt].join(' ').toLowerCase().includes(q);});};
function aaRiskRows(task){const v=av('risk');return awRows(task).filter(r=>v.riskFilter==='all'||aaRiskStatus(r)===v.riskFilter);}
awExportableRows=function(task,scope='all'){if(task.toolId==='risk'&&scope==='filtered')return aaRiskRows(task).filter(r=>auditFileAccess(file(r.doc)).download);return aaBase.awExportableRows(task,scope);};
awRisk=function(task){const v=av(),a=aaTaskView(task),all=awRows(task),rows=aaRiskRows(task),groups=[...new Set(rows.map(r=>v.riskGroup==='file'?r.doc:r.check))],statuses=[['all','全部'],['hit','待核验线索'],['nohit','未见线索'],['insufficient','资料不足']];a.page=Math.max(1,Math.min(a.page,Math.ceil(groups.length/8)||1));return '<header class="aa-result-heading"><h2 title="'+E(task.name)+'">'+E(task.name)+'</h2><span><strong>'+task.config.checks.length+'</strong> 个风险点 · <strong>'+new Set(all.map(r=>r.doc)).size+'</strong> 份资料</span></header>'+aaResultTools(task,true)+'<div class="aa-status-tabs" aria-label="检查结果状态">'+statuses.map(([key,label])=>'<button class="'+(v.riskFilter===key?'active':'')+'" data-action="aa-risk-status" data-status="'+key+'" aria-pressed="'+(v.riskFilter===key)+'">'+label+' <strong>'+(key==='all'?all.length:all.filter(r=>aaRiskStatus(r)===key).length)+'</strong></button>').join('')+'</div><div class="aa-viewbar">'+awTabs([['risk','按风险点'],['file','按资料']],v.riskGroup,'aw-risk-group')+'<div>'+A('展开全部','aw-expand-all')+A('收起全部','aw-collapse-all')+'</div></div><div class="aw-results-scroll aw-risk-groups aa-risk-groups">'+(groups.length?pageItems(groups,a.page,8).map(g=>{const matches=rows.filter(r=>(v.riskGroup==='file'?r.doc:r.check)===g),key='risk:'+v.riskGroup+':'+g,open=!v.collapsed.includes(key),node=task.config.riskNodes.find(n=>n.name===g),label=v.riskGroup==='file'?file(g)?.name:node?.path||g,limit=a.limits[key]||5;return '<section class="aw-risk-group"><button class="aw-group-head" data-action="aw-toggle-group" data-key="'+E(key)+'" aria-expanded="'+open+'">'+I(open?'down':'chevron','icon-sm')+'<span>'+E(label)+'</span><small>'+matches.length+' 条结果</small></button>'+(open?'<div class="aw-risk-items">'+matches.slice(0,limit).map(r=>{const status=aaRiskStatus(r),description=task.config.riskNodes.find(n=>n.name===r.check)?.description||'',detail=String(r.detail||'').replace('当前返回结果未匹配到相关线索，不能据此认定不存在风险。','本次未见相关线索。').replace('原文出现与本风险点相关的内容，请对照检查说明和业务凭证进一步核验。','资料中存在相关内容，需结合原文与业务凭证核验。');return '<article class="aw-risk-item"><div class="aa-finding-head"><h3>'+E(v.riskGroup==='file'?r.check:file(r.doc)?.name)+'</h3>'+(r.level?tag('等级：'+E(r.level),'amber'):'')+tag(status==='hit'?'待核验':status==='nohit'?'未见线索':'资料不足',status==='hit'?'amber':'')+'</div><p>'+E(detail)+'</p>'+(r.excerpt?'<blockquote>'+E(r.excerpt)+'</blockquote>':'')+'<div class="aa-finding-foot"><span title="'+E(description)+'">'+E(description)+'</span>'+awReviewLink(task,r,'查看原文')+'</div></article>';}).join('')+(matches.length>limit?B('再显示 '+Math.min(20,matches.length-limit)+' 条（共 '+matches.length+' 条）','aa-more-risk','ghost sm','data-key="'+E(key)+'"'):'')+'</div>':'')+'</section>';}).join(''):'<div class="aa-empty"><h3>当前条件下没有匹配结果</h3>'+B('查看全部检查结果','aa-risk-status','sm','data-status="all"')+'</div>')+'</div>'+aaPager('risk',groups.length,a.page,8,'组结果')+'<p class="aa-result-note">线索供进一步核验；未见线索不表示已排除风险。</p>';};
awReviewHTML=function(task,p){const html=aaBase.awReviewHTML(task,p);if(!AA_IDS.includes(task.toolId))return html;const root=document.createElement('div');root.innerHTML=html;root.querySelector('.aw-review-heading')?.classList.add('aa-review-heading');if(task.toolId==='risk')root.querySelectorAll('dd').forEach(n=>{if(n.textContent==='未匹配到线索')n.textContent='未见线索';if(n.textContent==='需核验')n.textContent='待核验';});return root.innerHTML;};
awOutputRows=function(task,rows){const table=aaBase.awOutputRows(task,rows);if(task.toolId!=='risk')return table;return table.map((r,i)=>i?r.map((cell,k)=>k===3?cell==='未匹配到线索'?'未见线索':cell==='需核验'?'待核验':cell:cell):r);};
meetingFilterModal=function(){const html=aaBase.meetingFilterModal(),root=document.createElement('div');root.innerHTML=html;root.querySelector('.modal')?.classList.add('aa-meeting-filter');root.querySelector('.modalhead p').textContent='按人员、日期、金额或议题内容查找本次结果。';const labels=root.querySelectorAll('.filter-grid label');labels[0].textContent='参会人员';const people=root.querySelector('[data-edit=participants]');people.placeholder='如：张三、李四';const regex=root.querySelector('[data-edit=regex]')?.closest('label'),hint=root.querySelector('.modalbody>.hint');if(regex){const details=document.createElement('details');details.className='aa-settings aa-regex';details.open=!!editorDraft.regex;details.innerHTML='<summary>关键词匹配选项</summary>';regex.childNodes[regex.childNodes.length-1].textContent=' 使用匹配表达式';details.append(regex);if(hint){hint.textContent='表达式支持文字、.、.*、^、$、|；金额未提取的记录不参与金额筛选。';details.append(hint);}root.querySelector('.modalbody').insertBefore(details,root.querySelector('#editor-error'));}return root.innerHTML;};
const aaFilterBase=awMeetingFiltered;
awMeetingFiltered=function(task){if(!task.meetingFilters?.participants)return aaFilterBase(task);const original=task.meetingFilters,participants=original.participants.replace(/[、，,；;\n]+/g,'|');if(participants===original.participants)return aaFilterBase(task);try{task.meetingFilters={...original,participants};return aaFilterBase(task);}finally{task.meetingFilters=original;}};
validate=function(show=true){if(state.toolId!=='meeting')return aaBase.validate(show);const errors=aaBase.validate(false).filter(e=>!['请填写会议风险的提示词','请填写风险分析的提示词'].includes(e)),c=ws().config;if(String(c.similarityThreshold??'').trim()===''||String(c.minClusterSize??'').trim()==='')errors.push('请填写议题聚类设置中的相似度阈值和每组最少议题数');const unique=[...new Set(errors)];if(show&&unique.length)openModal('validation',{errors:unique});return unique;};
modalContent=function(){const html=aaBase.modalContent();if(!aaActive())return html;if(modal==='aa-report-confirm')return modalFrame('重新生成风险报告','','<p>将按当前风险分析要求生成新报告，会议议题保持不变。</p>',B('取消','close-modal')+B('重新生成','aa-report-regenerate','primary'),'small');const root=document.createElement('div');root.innerHTML=html;if(modal==='aw-submit'){root.querySelector('.modalhead h2').textContent=state.toolId==='meeting'?'开始会议分析':'开始风险核查';root.querySelector('.modalhead p').textContent=state.toolId==='meeting'?'整理本次会议与议题，完成后可继续查看风险报告或提问。':'按所选风险点检查本次资料，结果保留线索与原文依据。';root.querySelector('[data-action=aw-submit-confirm]').textContent='确认开始';if(state.toolId==='meeting')root.querySelector('.ew-submit-summary>span:nth-child(2)').textContent='整理会议与议题';}if(modal==='aw-all-topics')root.querySelector('.modal')?.classList.add('aa-topics-dialog');if(modal==='v3-meeting-import'){root.querySelector('.modalhead p').textContent='恢复已有会议与议题，可继续风险分析和问答。';root.querySelector('.modalbody>.hint').textContent='支持本系统导出的Excel和JSON，以及原系统的会议结果格式。导入为新记录，原记录保留。';}return root.innerHTML;};
handleAction=function(action,el){if(!aaActive())return aaBase.handleAction(action,el);const task=currentTask(),a=aaView(),v=av(),index=+el?.dataset?.index;
 if(action==='aa-page'){const n=+el.dataset.step;if(el.dataset.kind==='topics-modal'){modalData.aaPage=(modalData.aaPage||1)+n;paintModal();}else{if(el.dataset.kind==='meeting-groups')a.groupPage+=n;else a.page+=n;render();if(el.dataset.kind==='meeting-groups'){a.page=1;const first=document.querySelector('.aw-meeting-groups>button');if(first)aaBase.handleAction('aw-meeting-select',first);}document.querySelector('.aa-risk-groups,.aw-meeting-detail .aw-table-scroll,.aa-meeting-table-area .aw-table-scroll')?.scrollTo({top:0});}return;}
 if(action==='aa-risk-status'){v.riskFilter=el.dataset.status;a.page=1;a.limits={};render();return;}
 if(action==='aa-more-risk'){a.limits[el.dataset.key]=(a.limits[el.dataset.key]||5)+20;const scroll=document.querySelector('.aa-risk-groups')?.scrollTop||0;render();document.querySelector('.aa-risk-groups')?.scrollTo({top:scroll});return;}
 if(action==='meeting-risk'&&task?.meetingRisk&&!task.riskGenerating)return openModal('aa-report-confirm');
 if(action==='aa-report-regenerate'){closeModal();return aaBase.handleAction('meeting-risk',{dataset:{}});}
 if(action==='aw-meeting-select')a.page=1;
 if(action==='suggest-question'){const out=aaBase.handleAction(action,el),input=document.getElementById('chat-question');if(input){av().questionDraft=input.value;const send=document.querySelector('[data-action=send-chat]');if(send)send.disabled=!input.value.trim()||!!task?.chatting;}return out;}
 if(['aw-meeting-view','aw-risk-group','aw-clear','aw-clear-meeting-filter','v2-save-editor'].includes(action)){a.page=1;a.groupPage=1;a.limits={};}
 if(action==='aw-risk-add'){modalData.editorQuery='';const out=aaBase.handleAction(action,el);document.querySelector('.aw-risk-editor tbody tr:last-child [data-aw-risk=name]')?.focus();return out;}
 if(action==='aw-risk-save'){const out=aaBase.handleAction(action,el);if(modal==='aw-risk-editor'){const names=modalData.nodes.map(r=>r.name.trim()),i=modalData.nodes.findIndex((r,j)=>!r.name.trim()||!r.path.trim()||!r.description.trim()||names.indexOf(r.name.trim())!==j);if(i>=0){modalData.editorQuery='';const row=document.querySelector('[data-aa-risk-index="'+i+'"]');if(row){row.hidden=false;row.querySelector('input:not([type=checkbox]),textarea')?.focus();}}}return out;}
 return aaBase.handleAction(action,el);
};
window.addEventListener('input',e=>{if(!aaActive())return;const el=e.target,key=el.dataset.aaInput;if(aaNumberInput(el)){e.stopImmediatePropagation();return;}if(key==='risk-search'){aaView().riskQuery=el.value;const list=document.getElementById('aa-risk-choices');if(list)list.innerHTML=aaRiskChoices(awConfig(),!!currentTask());}if(key==='risk-editor-search'&&modal==='aw-risk-editor'){modalData.editorQuery=el.value;document.querySelectorAll('[data-aa-risk-index]').forEach(row=>{const r=modalData.nodes[+row.dataset.aaRiskIndex];row.hidden=![r.name,r.path,r.description].join(' ').toLowerCase().includes(el.value.trim().toLowerCase());});}if(el.id==='aw-result-query'){aaView().page=1;aaView().groupPage=1;}if(el.id==='chat-question'){const send=document.querySelector('[data-action=send-chat]');if(send)send.disabled=!el.value.trim()||!!currentTask()?.chatting;}},true);
window.addEventListener('change',e=>{if(!aaActive())return;const el=e.target;if(aaNumberInput(el)){e.stopImmediatePropagation();return;}if(el.dataset.aaChange==='meeting-group'){e.stopImmediatePropagation();aaView().page=1;aaBase.handleAction('aw-meeting-select',{dataset:{id:el.value}});return;}if(el.dataset.aaChange==='scope'){e.stopImmediatePropagation();av().resultScope=el.value;av().resultFolder=null;aaView().page=1;aaView().groupPage=1;queueMicrotask(render);}},true);
document.addEventListener('click',e=>{const summary=e.target.closest('details[data-aa-details]>summary');if(summary&&aaActive())aaView()[summary.parentElement.dataset.aaDetails]=!summary.parentElement.open;},true);
document.addEventListener('toggle',e=>{const key=e.target.dataset?.aaDetails;if(key&&e.target.isConnected&&aaActive())aaView()[key]=e.target.open;},true);
render();
